    },
    {
      "kind": "exclusion",
      "text": "Major surgery or radiation therapy within 14 days of first administration of study drug.",
      "quote": "Major surgery or radiation therapy within 14 days of first administration of study drug",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has received treatment with an approved systemic therapy within 4 weeks of first dose of study drug, or has not yet recovered (ie, grade ≤1 or baseline) from any acute toxicities except for laboratory changes as described in inclusion criteria and as below: a. Neuropathy of grade ≤2 b. Alopecia of any grade",
      "quote": "Has received treatment with an approved systemic therapy within 4 weeks of first dose of study drug, or has not yet recovered (ie, grade ≤1 or baseline) from any acute toxicities except for laboratory changes as described in inclusion criteria and as below: a. Neuropathy of grade ≤2 b. Alopecia of any grade",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has another malignancy that is progressing or requires active treatment and/or history of malignancy other than cervical cancer within 3 years of date of first planned dose of study drug, except: a. Non-melanoma skin cancer that has undergone potentially curative therapy b. Ductal carcinoma in situ of the breast c. Any tumor that has been deemed to be effectively treated with definitive local control (with or without continued adjuvant hormonal therapy), and the patient is deemed to be in complete remission for at least 2 years prior to first dose of study drug, and no additional therapy is required during the study period. Note: Patients with hematologic malignancies (eg, chronic lymphocytic leukemia) are excluded.",
      "quote": "Has another malignancy that is progressing or requires active treatment and/or history of malignancy other than cervical cancer within 3 years of date of first planned dose of study drug, except: a. Non-melanoma skin cancer that has undergone potentially curative therapy b. Ductal carcinoma in situ of the breast c. Any tumor that has been deemed to be effectively treated with definitive local control (with or without continued adjuvant hormonal therapy), and the patient is deemed to be in complete remission for at least 2 years prior to first dose of study drug, and no additional therapy is required during the study period. Note: Patients with hematologic malignancies (eg, chronic lymphocytic leukemia) are excluded.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has any condition that requires ongoing/continuous corticosteroid therapy (>10 mg prednisone/day or anti-inflammatory equivalent) within 4 weeks prior to the first dose of study drug. Patients who require a brief course of steroids (up to 2 days in the week before enrollment) or physiologic replacement are not excluded.",
      "quote": "Has any condition that requires ongoing/continuous corticosteroid therapy (>10 mg prednisone/day or anti-inflammatory equivalent) within 4 weeks prior to the first dose of study drug.",
      "thresholds": [
        {
          "test": "prednisone",
          "op": ">",
          "value": 10,
          "unit": "mg/day"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Has ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments. The following are not exclusionary: vitiligo, childhood asthma that has resolved, endocrinopathies (such as hypothyroidism or type 1 diabetes) that require only hormone replacement, or psoriasis that does not require systemic treatment.",
      "quote": "Has ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has untreated or active primary brain tumor, CNS metastases, leptomeningeal disease or spinal cord compression. Exception: Patients with previously treated brain metastases may participate provided that the lesions are stable (without evidence of progression between 2 consecutive scans (eg, CT scan and/or MRI) at least 6 weeks prior to imaging obtained during the screening period), there is no evidence of new or enlarging brain metastases, and the patient does not require any immunosuppressive doses of systemic corticosteroids for management of brain metastases within 4 weeks of the first dose of study drug.",
      "quote": "Has untreated or active primary brain tumor, CNS metastases, leptomeningeal disease or spinal cord compression.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has encephalitis, meningitis, organic brain disease (eg, Parkinson’s disease) or uncontrolled seizures in the year prior to first dose of study drug.",
      "quote": "Has encephalitis, meningitis, organic brain disease (eg, Parkinson’s disease) or uncontrolled seizures in the year prior to first dose of study drug.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has a known history of, or any evidence of interstitial lung disease, or active, non-infectious pneumonitis within 5 years prior to the first dose of study drug. A history of radiation pneumonitis in the radiation field is permitted.",
      "quote": "Has a known history of, or any evidence of interstitial lung disease, or active, non-infectious pneumonitis within 5 years prior to the first dose of study drug.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has participated in a study of an investigational agent or an investigational device within 4 weeks of first dose of study drug.",
      "quote": "Has participated in a study of an investigational agent or an investigational device within 4 weeks of first dose of study drug.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has uncontrolled infection with human immunodeficiency virus (HIV), hepatitis B or hepatitis C infection; or diagnosis of immunodeficiency. Notes: Patients with known HIV infection who have controlled infection (undetectable viral load (HIV RNA PCR) and CD4 count above 350 either spontaneously or on a stable antiviral regimen) are permitted. Patients with hepatitis B (HepBsAg+) who have controlled infection (serum hepatitis B virus DNA PCR that is below the limit of detection AND receiving anti-viral therapy for hepatitis B) are permitted. Patients who are hepatitis C antibody positive (HCV Ab+) who have controlled infection (undetectable HCV RNA by PCR either spontaneously or in response to a successful prior course of anti-HCV therapy) are permitted.",
      "quote": "Has uncontrolled infection with human immunodeficiency virus (HIV), hepatitis B or hepatitis C infection; or diagnosis of immunodeficiency.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has any infection requiring hospitalization or treatment with IV anti-infectives within 2 weeks of first dose of study drug.",
      "quote": "Has any infection requiring hospitalization or treatment with IV anti-infectives within 2 weeks of first dose of study drug.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has received a live vaccine within 4 weeks of planned start of study medication.",
      "quote": "Has received a live vaccine within 4 weeks of planned start of study medication.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has had prior allogeneic stem cell transplantation, or autologous stem cell transplantation within 12 weeks of the start of study drug, unless discussed with and approved by the sponsor.",
      "quote": "Has had prior allogeneic stem cell transplantation, or autologous stem cell transplantation within 12 weeks of the start of study drug, unless discussed with and approved by the sponsor.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Recipients of organ transplants at any time unless discussed with and approved by the medical monitor.",
      "quote": "Recipients of organ transplants at any time unless discussed with and approved by the medical monitor.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has known allergy or hypersensitivity to components of study drug.",
      "quote": "Has known allergy or hypersensitivity to components of study drug",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has known psychiatric or substance abuse disorders that would interfere with participation with the requirements of the study.",
      "quote": "Has known psychiatric or substance abuse disorders that would interfere with participation with the requirements of the study.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has any medical condition, co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation in a clinical trial due to high safety risks and/or potential to affect interpretation of results of the study.",
      "quote": "Has any medical condition, co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation in a clinical trial due to high safety risks and/or potential to affect interpretation of results of the study",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Member of the clinical site study team or his/her immediate family, unless prior approval granted by the sponsor.",
      "quote": "Member of the clinical site study team or his/her immediate family, unless prior approval granted by the sponsor.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a positive serum/urine hCG pregnancy test must have pregnancy medically ruled out to be eligible for study. Breastfeeding women are also excluded.",
      "quote": "Patients with a positive serum/urine hCG pregnancy test must have pregnancy medically ruled out to be eligible for study. Breastfeeding women are also excluded.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Continued sexual activity in women of childbearing potential (WOCBP)*, or sexually active men, who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 6 months after the last dose. Highly effective contraceptive measures include: a. stable use of combined (estrogen and progestogen containing) hormonal contraception (oral, intravaginal, transdermal) or progestogen-only hormonal contraception (oral, injectable, implantable) associated with inhibition of ovulation initiated 2 or more menstrual cycles prior to screening b. intrauterine device (IUD); intrauterine hormone releasing system (IUS); c. bilateral tubal ligation d. vasectomized partner (provided that the male vasectomized partner is the sole sexual partner of the WOCBP study participant and that the vasectomized partner has obtained medical assessment of surgical success for the procedure) e. and/or sexual abstinence†,‡.",
      "quote": "Continued sexual activity in women of childbearing potential (WOCBP)*, or sexually active men, who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 6 months after the last dose.",
      "thresholds": []
    }
  ]
